-- FONKSIYONELLIK KODLARI BASLANGICI
-- ============================================

local UserInputService = game:GetService("UserInputService")
local VirtualInputManager = game:GetService("VirtualInputManager")
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer

-- FPS ve Ping Guncelleme
local fps = 0
local lastUpdate = tick()

RunService.RenderStepped:Connect(function()
	fps = fps + 1
	if tick() - lastUpdate >= 1 then
		LMG2L["TextLabel_14"].Text = "FPS:" .. tostring(fps)
		fps = 0
		lastUpdate = tick()
	end
end)

-- Ping guncelleme (her 2 saniyede bir)
task.spawn(function()
	while true do
		task.wait(2)
		local ping = LocalPlayer:GetNetworkPing() * 1000 -- ms cinsinden
		LMG2L["TextLabel_15"].Text = "PING:" .. tostring(math.floor(ping))
	end
end)

-- Mouse Scroll (U/D) Fonksiyonlari
LMG2L["TextButton_6"].InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
		VirtualInputManager:SendMouseWheelEvent(0, 0, true, game)
	end
end)

LMG2L["TextButton_7"].InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
		VirtualInputManager:SendMouseWheelEvent(0, 0, false, game)
	end
end)

-- Mouse Left-Right (kamera dondurme)
local camera = workspace.CurrentCamera
local player = LocalPlayer

LMG2L["TextButton_8"].InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
		-- Sola dondur (sürekli)
		local connection
		connection = RunService.RenderStepped:Connect(function()
			if not LMG2L["TextButton_8"] or not LMG2L["TextButton_8"].Parent then
				connection:Disconnect()
				return
			end
			local currentCFrame = camera.CFrame
			camera.CFrame = currentCFrame * CFrame.Angles(0, math.rad(2), 0)
		end)

		LMG2L["TextButton_8"].InputEnded:Connect(function()
			connection:Disconnect()
		end)
	end
end)

LMG2L["TextButton_9"].InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
		-- Saga dondur (sürekli)
		local connection
		connection = RunService.RenderStepped:Connect(function()
			if not LMG2L["TextButton_9"] or not LMG2L["TextButton_9"].Parent then
				connection:Disconnect()
				return
			end
			local currentCFrame = camera.CFrame
			camera.CFrame = currentCFrame * CFrame.Angles(0, math.rad(-2), 0)
		end)

		LMG2L["TextButton_9"].InputEnded:Connect(function()
			connection:Disconnect()
		end)
	end
end)

-- WASD Hareket Fonksiyonlari
